%[text] # Steel4 cyclic material test
%[text] A zeroLength element with unit area is subjected to a symmetric cyclic
%[text] deformation history. Its deformation and force are interpreted as steel
%[text] strain and stress, respectively.
clearvars;
close all;
clc;
exampleFolder = fileparts(mfilename("fullpath"));
figDir = fullfile(exampleFolder, 'figures');
if ~isfolder(figDir)
    mkdir(figDir);
end
%%
%[text] ## Material parameters

Fy = 0.345;                 % kN/mm^2
E0 = 200.0;                 % kN/mm^2
b = 0.01;
R0 = 18.0;
r1 = 0.925;
r2 = 0.15;
Fu = 1.20*Fy;
Ru = 20.0;
%%
%[text] ## Cyclic strain history
%[text] Two complete cycles are applied at each amplitude.

amplitudes = [0.002, 0.005, 0.010, 0.020, 0.040, 0.080];
targets = 0.0;
for amplitude = amplitudes
    targets = [targets, amplitude, -amplitude, ...
        amplitude, -amplitude, 0.0]; %#ok<AGROW>
end
maximumIncrement = 2.0e-5;
%%
%[text] ## OpenSees model

opsMAT = OpenSeesMatlab();
ops = opsMAT.opensees;

ops.wipe();
ops.model('BasicBuilder', '-ndm', 2, '-ndf', 3);
ops.node(1, 0.0, 0.0);
ops.node(2, 0.0, 0.0);
ops.fix(1, 1, 1, 1);
ops.fix(2, 0, 1, 1);

materialTag = 1;
elementTag = 1;

ops.uniaxialMaterial('Steel4', materialTag, Fy, E0, ...
    '-kin', b, R0, r1, r2, '-ult', Fu, Ru);
%%
%[text] ## Column fiber section
%[text] H300x220x8x14 section with the same 80-fiber discretization used by the
%[text] frame columns: 24 fibers in each flange and 32 fibers in the web.

opsMAT.pre.setSectionGeometryRecorder(true);

sectionTag = 1;
d = 300.0;
bf = 220.0;
tw = 8.0;
tf = 14.0;

ops.section('Fiber', sectionTag);
ops.patch('rect', materialTag, 2, 12, ...
    0.5*d-tf, -0.5*bf, 0.5*d, 0.5*bf);
ops.patch('rect', materialTag, 16, 2, ...
    -0.5*d+tf, -0.5*tw, 0.5*d-tf, 0.5*tw);
ops.patch('rect', materialTag, 2, 12, ...
    -0.5*d, -0.5*bf, -0.5*d+tf, 0.5*bf);

sectionFigure = figure('Color', 'w', 'Units', 'centimeters', ... %[output:39eab462]
    'Position', [2, 2, 13.5, 15.5]); %[output:39eab462]
sectionAxes = axes(sectionFigure); %[output:39eab462]
colormap(sectionAxes, [0.10, 0.45, 0.75]); %[output:39eab462]
opsMAT.pre.plotSection(sectionTag, sectionAxes); %[output:39eab462]
opsMAT.pre.setSectionGeometryRecorder(false);

xlabel(sectionAxes, 'Section depth, y (mm)', 'FontSize', 18); %[output:39eab462]
ylabel(sectionAxes, 'Section width, z (mm)', 'FontSize', 18); %[output:39eab462]
title(sectionAxes, 'H300x220x8x14 column section', 'FontSize', 18); %[output:39eab462]
set(sectionAxes, 'FontName', 'Arial', 'FontSize', 15, ... %[output:39eab462]
    'LineWidth', 1.0, 'TickDir', 'out'); %[output:39eab462]
axis(sectionAxes, 'equal'); %[output:39eab462]
exportgraphics(sectionFigure, fullfile(figDir, 'Steel4ColumnFiberSection.pdf'), ... %[output:group:86ff58de] %[output:39eab462]
    'ContentType', 'vector'); %[output:group:86ff58de] %[output:39eab462]

sectionData = table( ...
    ["top_flange"; "web"; "bottom_flange"], ...
    [0.5*d-tf; -0.5*d+tf; -0.5*d], ...
    [0.5*d; 0.5*d-tf; -0.5*d+tf], ...
    [-0.5*bf; -0.5*tw; -0.5*bf], ...
    [0.5*bf; 0.5*tw; 0.5*bf], ...
    [2; 16; 2], [12; 2; 12], ...
    'VariableNames', {'Component','YMin_mm','YMax_mm','ZMin_mm', ...
    'ZMax_mm','NY','NZ'});
writetable(sectionData, ...
    fullfile(figDir, 'Steel4ColumnFiberSection.csv'));

ops.element('zeroLength', elementTag, 1, 2, ...
    '-mat', materialTag, '-dir', 1);

ops.timeSeries('Linear', 1);
ops.pattern('Plain', 1, 1);
ops.load(2, 1.0, 0.0, 0.0);

ops.constraints('Plain');
ops.numberer('Plain');
ops.system('BandGeneral');
ops.test('NormUnbalance', 1.0e-10, 30, 0);
ops.algorithm('Newton');
ops.integrator('LoadControl', 0.0);
ops.analysis('Static');
%%
%[text] ## Displacement-controlled cyclic analysis

strain = 0.0;
stress = 0.0;
tangent = E0;
cumulativeEnergy = 0.0;

for targetIndex = 2:numel(targets)
    currentStrain = ops.nodeDisp(2, 1);
    change = targets(targetIndex) - currentStrain;
    numberOfSteps = max(1, ceil(abs(change)/maximumIncrement));
    increment = change/numberOfSteps;

    ops.integrator('DisplacementControl', 2, 1, increment);

    for step = 1:numberOfSteps
        code = ops.analyze(1);
        if code ~= 0
            error('Steel4CyclicTest:Convergence', ...
                'Analysis failed while approaching strain %.5f.', ...
                targets(targetIndex));
        end

        currentStrain = ops.nodeDisp(2, 1);
        currentStress = ops.eleResponse( ...
            elementTag, 'material', 1, 'stress');
        currentTangent = ops.eleResponse( ...
            elementTag, 'material', 1, 'tangent');

        strain(end+1,1) = currentStrain; %#ok<SAGROW>
        stress(end+1,1) = currentStress; %#ok<SAGROW>
        tangent(end+1,1) = currentTangent; %#ok<SAGROW>
        cumulativeEnergy(end+1,1) = cumulativeEnergy(end) + ...
            0.5*(stress(end) + stress(end-1))* ...
            (strain(end) - strain(end-1)); %#ok<SAGROW>
    end
end

ops.wipe();
%%
%[text] ## Results

stressMPa = 1000.0*stress;
tangentGPa = tangent;
energyMPa = 1000.0*cumulativeEnergy;

results = table(100.0*strain, stressMPa, ...
    'VariableNames', {'Strain_pct','Stress_MPa'});

fig = figure('Color', 'w', 'Units', 'centimeters', ... %[output:13eff0ea]
    'Position', [2, 2, 17.5, 13.0]); %[output:13eff0ea]
ax = axes(fig); %[output:13eff0ea]
hold(ax, 'on'); %[output:13eff0ea]
box(ax, 'on'); %[output:13eff0ea]
grid(ax, 'on'); %[output:13eff0ea]

plot(ax, 100.0*strain, stressMPa, '-', ... %[output:13eff0ea]
    'Color', [0.00, 0.35, 0.65], 'LineWidth', 2.25); %[output:13eff0ea]
yline(ax, 1000.0*Fu, '--', 'F_u', ... %[output:13eff0ea]
    'Color', [0.75, 0.15, 0.10], 'LineWidth', 2.0); %[output:13eff0ea]
yline(ax, -1000.0*Fu, '--', ... %[output:13eff0ea]
    'Color', [0.75, 0.15, 0.10], 'LineWidth', 2.0, ... %[output:13eff0ea]
    'HandleVisibility', 'off'); %[output:13eff0ea]
yline(ax, 1000.0*Fy, ':', 'F_y', ... %[output:13eff0ea]
    'Color', [0.25, 0.25, 0.25], 'LineWidth', 2.0); %[output:13eff0ea]
yline(ax, -1000.0*Fy, ':', ... %[output:13eff0ea]
    'Color', [0.25, 0.25, 0.25], 'LineWidth', 2.0, ... %[output:13eff0ea]
    'HandleVisibility', 'off'); %[output:13eff0ea]
ylim([-501 590]); %[output:13eff0ea]
grid off; %[output:13eff0ea]

xlabel(ax, 'Steel strain (%)', 'Interpreter', 'none', 'FontSize', 19); %[output:13eff0ea]
ylabel(ax, 'Steel stress (MPa)', 'FontSize', 19); %[output:13eff0ea]
set(ax, 'FontName', 'Arial', 'FontSize', 16, ... %[output:13eff0ea]
    'LineWidth', 1.0, 'TickDir', 'out', ... %[output:13eff0ea]
    'GridLineStyle', '--', 'GridAlpha', 0.20); %[output:13eff0ea]

referenceLabels = findall(ax, 'Type', 'ConstantLine');
set(referenceLabels, 'FontSize', 16); %[output:13eff0ea]

text(ax, 0.02, 0.97, ... %[output:13eff0ea]
    sprintf('F_y = %.0f MPa, F_u = %.0f MPa', ... %[output:13eff0ea]
    1000.0*Fy, 1000.0*Fu), ... %[output:13eff0ea]
    'Units', 'normalized', 'VerticalAlignment', 'top', ... %[output:13eff0ea]
    'FontSize', 16, 'BackgroundColor', 'w', 'Margin', 4); %[output:13eff0ea]

exportgraphics(fig, fullfile(figDir, 'Steel4CyclicHysteresis.pdf'), ... %[output:group:0fcb57b1] %[output:13eff0ea] %[output:2a38631a]
    'ContentType', 'vector'); %[output:group:0fcb57b1] %[output:13eff0ea] %[output:2a38631a]
writetable(results, fullfile(figDir, 'Steel4CyclicHysteresis.csv'));
% exportgraphics(fig, 'figures/Steel4CyclicHysteresis.png', ...
%     'Resolution', 300);

fprintf('Steel4 cyclic test completed.\n'); %[output:8046e260]
fprintf('Maximum stress = %.3f MPa\n', max(abs(stressMPa))); %[output:2fe0b425]
fprintf('Final accumulated loop integral = %.3f MPa\n', ... %[output:group:232d9e45] %[output:7b9a2e45]
    energyMPa(end)); %[output:group:232d9e45] %[output:7b9a2e45]

